package com.example.data.curriculum

import com.example.data.model.*

/** Authored offline practice, one core/follow-up pair for every unit and CEFR level. */
object ExpandedCurriculum {
    private data class Entry(
        val level: CefrLevel, val unit: Int,
        val english: String, val spanish: String, val translation: String,
        val questionEnglish: String, val questionSpanish: String, val questionTranslation: String,
        val note: String
    )

    private val entries: List<Entry> by lazy {
        raw.trim().lines().filter { it.isNotBlank() }.map { line ->
            val p = line.split('|')
            require(p.size == 9) { "Invalid curriculum row" }
            Entry(CefrLevel.valueOf(p[0]), p[1].toInt(), p[2], p[3], p[4], p[5], p[6], p[7], p[8])
        }.also { rows ->
            require(rows.size == 72 && rows.map { it.level to it.unit }.toSet().size == 72)
        }
    }

    fun itemsFor(language: TargetLanguage, level: CefrLevel, unit: Int, themeAr: String): List<SentenceLessonItem> {
        require(unit in 1..12)
        val levelRows = entries.filter { it.level == level }.sortedBy { it.unit }
        val row = levelRows[unit - 1]
        val en = language == TargetLanguage.EN
        return (0..1).map { variant ->
            val target = if (variant == 0) { if (en) row.english else row.spanish }
                else { if (en) row.questionEnglish else row.questionSpanish }
            val counterpart = if (variant == 0) { if (en) row.questionEnglish else row.questionSpanish }
                else { if (en) row.english else row.spanish }
            val translation = if (variant == 0) row.translation else row.questionTranslation
            val otherTranslation = if (variant == 0) row.questionTranslation else row.translation
            val distractors = listOf(levelRows[unit % 12], levelRows[(unit + 4) % 12]).map {
                if (variant == 0) it.translation else it.questionTranslation
            }
            val correct = (unit + variant) % 3
            val options = distractors.toMutableList().apply { add(correct, translation) }
            SentenceLessonItem(
                id = "expanded_${language.code.lowercase()}_${level.code.lowercase()}_u${unit}_p$variant",
                language = language, cefrLevel = level, unitNumber = unit, lessonNumber = 1,
                sentence = target, dialectVariantAlt = "", arabicTranslation = translation,
                expressionNoteAr = row.note,
                grammarInContextAr = if (variant == 0) "اقرأ العبارة، وحدد دور الأفعال والروابط إن وجدت. قارنها بالمثال، ثم غيّر تفصيلًا واحدًا مع الحفاظ على المعنى العام." else "لاحظ ترتيب السؤال وعلامته. قارن السؤال بالمثال، ثم أجب بمعلومة من عندك.",
                realWorldUsageAr = "تدريب ${level.code} في سياق: $themeAr. بدّل التفاصيل بمثال خيالي من اختيارك دون مشاركة معلومات حساسة.",
                similarExamples = listOf(counterpart to otherTranslation),
                comprehensionQuestionAr = if (variant == 0) "ما المعنى الأقرب للجملة في هذا السياق؟" else "ما المعنى الصحيح لهذا السؤال؟",
                optionsAr = options, correctOptionIndex = correct
            )
        }
    }

    fun examQuestionsFor(language: TargetLanguage, level: CefrLevel): List<ExamQuestion> =
        (1..12).map { unit ->
            val item = itemsFor(language, level, unit, "فهم المعنى")[unit % 2]
            ExamQuestion(
                id = "expanded_exam_${language.code.lowercase()}_${level.code.lowercase()}_u$unit",
                skill = if (unit % 2 == 0) SkillType.LISTENING else SkillType.READING,
                promptAr = if (unit % 2 == 0) "استمع للنص ثم اختر معناه الأقرب:" else "اقرأ النص ثم اختر معناه الأقرب:",
                stimulusTarget = item.sentence, options = item.optionsAr, correctIndex = item.correctOptionIndex
            )
        }

